function marketMapLayout(stocks,width=1000,height=420){
 const items=stocks.filter(s=>Number.isFinite(s.cap)&&s.cap>0).slice().sort((a,b)=>b.cap-a.cap),total=items.reduce((n,s)=>n+s.cap,0);if(!total)return [];
 let pending=items.map(stock=>({stock,area:stock.cap/total*width*height})),x=0,y=0,w=width,h=height,row=[];const leaves=[];
 const worst=(row,side)=>{if(!row.length)return Infinity;const sum=row.reduce((n,s)=>n+s.area,0),max=Math.max(...row.map(s=>s.area)),min=Math.min(...row.map(s=>s.area));return Math.max(side*side*max/(sum*sum),sum*sum/(side*side*min))};
 function place(){const area=row.reduce((n,s)=>n+s.area,0);if(w>=h){const width=area/h;let cy=y;for(const item of row){const height=item.area/width;leaves.push({stock:item.stock,x,y:cy,w:width,h:height});cy+=height}x+=width;w=Math.max(0,w-width)}else{const height=area/w;let cx=x;for(const item of row){const width=item.area/height;leaves.push({stock:item.stock,x:cx,y,w:width,h:height});cx+=width}y+=height;h=Math.max(0,h-height)}row=[]}
 while(pending.length){const item=pending[0],side=Math.min(w,h);if(!row.length||worst([...row,item],side)<=worst(row,side)){row.push(pending.shift())}else place()}if(row.length)place();return leaves;
}
function marketMapColor(change){if(!Number.isFinite(change)||change===0)return '#354760';const t=Math.min(Math.abs(change)/3,1),a=change>0?[32,91,78]:[106,44,59],b=change>0?[7,120,82]:[189,51,72];return '#'+a.map((v,i)=>Math.round(v+(b[i]-v)*t).toString(16).padStart(2,'0')).join('')}
function marketMapMarkup(rows){if(!rows.length)return '<div class="empty">No market-cap data for this selection.</div>';return `<div class="treemap-stage"><div class="stock-treemap" role="group" aria-label="Company market map; tile area represents market capitalization">${marketMapLayout(rows).map(({stock:s,x,y,w,h})=>{const size=w*h/420000;return `<button class="treemap-tile ${size<.025?'tile-small':size>.09?'tile-large':''}" data-company="${s.rank}" data-map-stock="${s.rank}" data-map-cap="${s.cap}" style="left:${x/10}%;top:${y/4.2}%;width:${w/10}%;height:${h/4.2}%;--tile-font:${Math.max(10,Math.min(24,Math.sqrt(size)*52)).toFixed(2)}px;--tile-color:${marketMapColor(s.change)}" aria-label="${escapeHtml(s.name)}, market cap ${amount(s.cap)}, day change ${s.change==null?'unavailable':s.change.toFixed(2)+'%'}"><span class="tile-symbol">${escapeHtml(stockTickerLabel(s).replace(/\.(NS|BO)$/, ''))}</span><span class="tile-name">${escapeHtml(s.name)}</span><strong class="tile-change">${s.change==null?'—':(s.change>0?'+':'')+s.change.toFixed(2)+'%'}</strong><small class="tile-cap">${s.liveCapEstimated?'≈ ':''}${amount(s.cap)}</small></button>`}).join('')}</div><div class="treemap-tooltip" hidden role="status"></div></div><div class="treemap-footer"><span>Area = market cap of shown companies · Color = daily change</span><div class="map-color-scale" aria-label="Daily percentage change color scale"><span>−3%</span><i style="background:#bd3348"></i><i style="background:#913447"></i><i style="background:#354760"></i><i style="background:#1b725b"></i><i style="background:#077852"></i><span>+3%</span></div><span>Hover for details · Select to explore</span></div>`}
let marketMapObserver=null;
function responsiveMarketMap(rows,stage){marketMapObserver?.disconnect();const map=stage.querySelector('.stock-treemap');let previous='';const layout=()=>{if(!map.isConnected){marketMapObserver?.disconnect();return}const width=map.clientWidth,height=map.clientHeight,key=width+':'+height;if(!width||!height||key===previous)return;previous=key;for(const item of marketMapLayout(rows,width,height)){const tile=map.querySelector('[data-map-stock="'+item.stock.rank+'"]');if(!tile)continue;tile.style.left=item.x/width*100+'%';tile.style.top=item.y/height*100+'%';tile.style.width=item.w/width*100+'%';tile.style.height=item.h/height*100+'%';const name=tile.querySelector('.tile-name'),cap=tile.querySelector('.tile-cap');name.style.display=item.w>=100&&item.h>=80?'':'none';cap.style.display=item.h>=44&&item.w>=48?'':'none'}};layout();marketMapObserver=new ResizeObserver(layout);marketMapObserver.observe(map)}
function bindMarketMap(rows){const stage=document.querySelector('.treemap-stage'),tooltip=document.querySelector('.treemap-tooltip');if(!stage||!tooltip)return;responsiveMarketMap(rows,stage);document.querySelectorAll('[data-map-stock]').forEach(tile=>{const show=event=>{const s=rows.find(s=>s.rank===+tile.dataset.mapStock);if(!s)return;const sum=rows.reduce((n,s)=>n+s.cap,0);tooltip.innerHTML=`<strong>${escapeHtml(s.name)}</strong><dl><div><dt>Cap</dt><dd>${s.liveCapEstimated?'≈ ':''}${amount(s.cap)}</dd></div><div><dt>Price</dt><dd>${stockPrice(s)}</dd></div><div><dt>Day</dt><dd class="${s.change>0?'positive':s.change<0?'negative':''}">${s.change==null?'—':(s.change>0?'+':'')+s.change.toFixed(2)+'%'}</dd></div><div><dt>Share shown</dt><dd>${(s.cap/sum*100).toFixed(2)}%</dd></div></dl>`;tooltip.hidden=false;const r=tile.getBoundingClientRect();positionChartTooltip(tooltip,event?.clientX??r.right,event?.clientY??r.top)};tile.addEventListener('pointerenter',show);tile.addEventListener('pointermove',show);tile.addEventListener('focus',e=>{show(e);requestAnimationFrame(()=>{if(document.activeElement===tile)show(e)})});tile.addEventListener('pointerleave',()=>tooltip.hidden=true);tile.addEventListener('blur',()=>tooltip.hidden=true)})}
